from __future__ import division, absolute_import, print_function,\
    unicode_literals
from builtins import object, range
import re
import sys
import time
from taf.ul.trs_e2e_fw.lib.remote_connection.remoteconnection import RemoteConnection
from taf.ul.trs_e2e_fw.lib.utils.front_haul_modules.rf_module.rf_module import RfModule
from taf.ul.trs_e2e_fw.lib.traffic.capture.tcpdump.exception import TcpdumpExecutionError
from taf.ul.trs_e2e_fw.lib.traffic.capture.tcpdump.exception import ProcessIsAlreadyRunning
from taf.ul.trs_e2e_fw.lib.traffic.capture.tcpdump.exception import StopProcessError, StartProcessError

import logging

from future import standard_library
standard_library.install_aliases()


class BaseTcpdump(object):

    """ Class to handle packets sniffer. """

    def __init__(self, ssh_client, tcpdump_dir, interface, log_dir, snaplen, preferences, sudo):

        """
        :param ssh_client:              SSHLibrary instance with established connection.
        :param string tcpdump_dir:       Path to dictionary where tcpdump is located.
        :param string interface:        Local or remote machine interface which is used to packects capture.
        :param string log_dir:          Directory path where pcap file is stored.
        :param integer snaplen:         Amount of data for each frame that is captured.


        """
        self._ssh = ssh_client
        self._tcpdump_dir = tcpdump_dir
        self._interface = interface
        self._log_dir = log_dir
        self._setup_log_dir(log_dir)
        self._snaplen = snaplen
        self._pid = None
        self._display_filter = self._get_display_filter()
        self._preferences = preferences
        self._sudo = sudo

    @property
    def pid(self):
        """ Get process id.

        :return:        Shell process id.
        :rtype:         string
        """
        return self._pid

    @pid.setter
    def pid(self, pid):
        """ Set process id.

        :param string pid:      Shell process id.
        """
        if self._pid is not None:
            raise ProcessIsAlreadyRunning("{} process is running".format(
                self.__class__.__name__))
        self._pid = pid

    def start_process(self, cmd, timecheck=10):
        """ Start process.

        :param string cmd:           Command to run.
        :param string timecheck:     Number of seconds to check if tcpdump
                                     execution exists (default: 10).
        """
        self.pid = self._exec_get_pid(cmd)
        # self.pid = self._execute(cmd)
        logging.debug("pid is {}".format(self.pid))
        self._is_process_started(timecheck)

    def stop_process(self):
        """Stop process.

        """
        logging.debug("#### sudo to kill process is {}".format(self._sudo))
        cmd = 'sudo kill -2 {} || true'.format(self.pid) if self._sudo else 'kill -2 {} || true'.format(self.pid)
        for i in range(0, 3):
            self._execute(cmd)
            if self._is_process_stopped():
                return
        raise StopProcessError("{} process was not be stopped. Tcpdump pid"
                               " {} is still existing".format(self.__class__.__name__, self.pid))

    def _execute(self, cmd):
        if isinstance(self._ssh, str):
            # out, err, rc = self._execute_on_rfmodule(cmd)
            out, err, rc = RemoteConnection().execute_command_on_shell(command=cmd, alias=self._ssh, timeout=5,
                                                                       return_rc=True)
        else:
            out, err, rc = self._ssh.execute_command(cmd)
        if rc == 0:
            if "Permission denied" in err:
                raise TcpdumpExecutionError("Got Permission Denied while executing {}.\nMake sure you have permission".format(cmd))
            return out
        raise TcpdumpExecutionError(err)

    def _exec_get_pid(self, cmd):
        pid = None
        out = self._execute(cmd)
        logging.debug("output from _exec_get_pid is {}".format(out))
        pid = self._match_pattern(out, r'^\d+$')
        if pid is None:
            logging.debug("pid not found")
            raise TcpdumpExecutionError("Process Not Started {}".format(out))
        return pid

    def _match_pattern(self, output, match_pattern):
        logging.debug("split output {}".format(output.splitlines()))
        for line in output.splitlines():
            logging.debug("#### Line is {}".format(line))
            match = re.findall(match_pattern, line.strip())
            if len(match) > 0:
                logging.debug("match is {}".format(match[0]))
                return match[0]
        else:
            logging.debug("Could not find match for pattern {}".format(match_pattern))
            return None 

    def _execute_on_rfmodule(self, cmd, timeout=5):
        out, stderr = RfModule().send_cmd_recv_output(cmd, timeout=timeout, alias=self._ssh, return_err=True)
        rc = 1 if stderr else 0
        return out, stderr, rc

    def _get_file(self, src, dst, sudo=False):
        if isinstance(self._ssh, str):
            logging.debug("#### src is {} \n dest is {}".format(src, dst))
            if sudo:
                RemoteConnection().execute_command_on_shell(command='sudo scp {} {}'.format(src, dst), alias=self._ssh)
                RemoteConnection().execute_command_on_shell(command='exit', alias=self._ssh)
            else:
                logging.debug("#### Copy using get_file keyword")
                file_name = RemoteConnection().get_file(src, dst, alias=self._ssh)
                return file_name
        else:
            return self._ssh.get_file(source=src, destination=dst)

    def _is_process_stopped(self):
        start = time.time()
        try:
            while time.time() - start < 10:
                if not self._pid_exists():
                    return True
                time.sleep(1)
        except TcpdumpExecutionError:
            self._pid = None
            sys.exc_info()
            return True
        else:
            return False

    def _is_process_started(self, timecheck):
        start = time.time()
        try:
            while time.time() - start < timecheck:
                if self._pid_exists():
                    return
                time.sleep(1)
        except TcpdumpExecutionError:
            error = self._execute('cat {}/{}_tcpdump_error_log'.format(self._log_dir, self.__class__.__name__))
            self._pid = None
            raise StartProcessError("{} process was not started\n{}".format(self.__class__.__name__, error))

    def _pid_exists(self):
        # self._execute("ps -ef | awk '{{print $2}}' | grep '^{}$'".format(self.pid))
        out = self._execute("ps -ef | awk '{print $2}' | grep '^"+self._pid+"$'")
        # out = self._execute("ps -ef | | awk '{print $2}' | grep '^{}$'".format(self._pid))
        logging.debug("#### output from _pid_exists is {}".format(out))
        pid = self._match_pattern(out, r'^\d+$')
        if pid is None:
            logging.debug("pid not found")
            return False
        logging.debug("pid found {}".format(pid))
        return True

    def _setup_log_dir(self, log_dir):
        try:
            self._execute('[ -d {} ]'.format(log_dir))
        except TcpdumpExecutionError:
            self._execute('mkdir -p {}'.format(log_dir))

    def _get_display_filter(self):
        try:
            self._execute('{}/tcpdump -h | grep "<display filter>"'.format(self._tcpdump_dir))
        except TcpdumpExecutionError:
            return '-R'
        else:
            return '-Y'
